def from_dict(
    cls: type[SpecificPreTrainedConfigType], config_dict: dict[str, Any], **kwargs
) -> SpecificPreTrainedConfigType:
    """
    Instantiates a [`PreTrainedConfig`] from a Python dictionary of parameters.

    Args:
        config_dict (`dict[str, Any]`):
            Dictionary that will be used to instantiate the configuration object. Such a dictionary can be
            retrieved from a pretrained checkpoint by leveraging the [`~PreTrainedConfig.get_config_dict`] method.
        kwargs (`dict[str, Any]`):
            Additional parameters from which to initialize the configuration object.

    Returns:
        [`PreTrainedConfig`]: The configuration object instantiated from those parameters.
    """
    return_unused_kwargs = kwargs.pop("return_unused_kwargs", False)

    # The commit hash might have been updated in the `config_dict`, we don't want the kwargs to erase that update.
    if "_commit_hash" in kwargs and "_commit_hash" in config_dict:
        kwargs.setdefault("_commit_hash", config_dict["_commit_hash"])

    # To remove arg here are those passed along for our internal telemetry but we still need to remove them
    to_remove = ["_from_auto", "_from_pipeline"]
    valid_fields = [
        "num_labels",
        "attn_implementation",
        "experts_implementation",
        "output_attentions",
        "torch_dtype",
        "dtype",
        "name_or_path",
    ]
    for key, value in kwargs.items():
        if key in valid_fields:
            if key not in ["torch_dtype", "dtype"]:
                config_dict[key] = value
                to_remove.append(key)
            elif value != "auto":
                config_dict[key] = value

    config = cls(**config_dict)

    for key, value in kwargs.items():
        if hasattr(config, key):
            current_attr = getattr(config, key)
            # To authorize passing a custom subconfig as kwarg in models that have nested configs.
            # We need to update only custom kwarg values instead and keep other attr in subconfig.
            if isinstance(current_attr, PreTrainedConfig) and isinstance(value, dict):
                current_attr_updated = current_attr.to_dict()
                current_attr_updated.update(value)
                value = current_attr.__class__(**current_attr_updated)
            setattr(config, key, value)
            to_remove.append(key)

    for key in to_remove:
        kwargs.pop(key, None)

    logger.info(f"Model config {config}")
    if return_unused_kwargs:
        return config, kwargs
    else:
        return config

@classmethod
def from_json_file(
    cls: type[SpecificPreTrainedConfigType], json_file: str | os.PathLike
) -> SpecificPreTrainedConfigType:
    """
    Instantiates a [`PreTrainedConfig`] from the path to a JSON file of parameters.

    Args:
        json_file (`str` or `os.PathLike`):
            Path to the JSON file containing the parameters.

    Returns:
        [`PreTrainedConfig`]: The configuration object instantiated from that JSON file.

    """
    config_dict = cls._dict_from_json_file(json_file)
    return cls(**config_dict)

@classmethod
def _dict_from_json_file(cls, json_file: str | os.PathLike):
    with open(json_file, encoding="utf-8") as reader:
        text = reader.read()
    config_dict = json.loads(text)

    return cls._decode_special_floats(config_dict)

@classmethod
def _encode_special_floats(cls, obj: Any) -> Any:
    """
    Iterates over the passed object and encode specific floats that cannot be JSON-serialized. Python's JSON
    engine saves floats like `Infinity` (+/-) or `NaN` which are not compatible with other JSON engines.

    It serializes floats like `Infinity` as an object: `{'__float__': Infinity}`.
    """
    if isinstance(obj, float):
        if math.isnan(obj):
            return {_FLOAT_TAG_KEY: "NaN"}
        if obj == float("inf"):
            return {_FLOAT_TAG_KEY: "Infinity"}
        if obj == float("-inf"):
            return {_FLOAT_TAG_KEY: "-Infinity"}
        return obj

    if isinstance(obj, dict):
        return {k: cls._encode_special_floats(v) for k, v in obj.items()}

    if isinstance(obj, (list, tuple)):
        return [cls._encode_special_floats(v) for v in obj]

    return obj

@classmethod
def _decode_special_floats(cls, obj: Any) -> Any:
    """
    Iterates over the passed object and decode specific floats that cannot be JSON-serialized. Python's JSON
    engine saves floats like `Infinity` (+/-) or `NaN` which are not compatible with other JSON engines.

    This method deserializes objects like `{'__float__': Infinity}` to their float values like `Infinity`.
    """
    if isinstance(obj, dict):
        if set(obj.keys()) == {_FLOAT_TAG_KEY} and isinstance(obj[_FLOAT_TAG_KEY], str):
            tag = obj[_FLOAT_TAG_KEY]
            if tag in _FLOAT_TAG_VALUES:
                return _FLOAT_TAG_VALUES[tag]
            return obj

@staticmethod
def _load_pretrained_model(
    model: "PreTrainedModel",
    state_dict: dict | None,
    checkpoint_files: list[str] | None,
    load_config: LoadStateDictConfig,
    expected_keys: list[str] | None = None,
) -> tuple[LoadStateDictInfo, dict]:
    """Perform the actual loading of some checkpoints into a `model`, by reading them from disk and dispatching them accordingly."""
    hf_quantizer = load_config.hf_quantizer
    is_quantized = load_config.is_quantized
    is_hqq_or_quark = hf_quantizer is not None and hf_quantizer.quantization_config.quant_method in {
        QuantizationMethod.HQQ,
        QuantizationMethod.QUARK,
    }

    # Model's definition arriving here is final (TP hooks added, quantized layers replaces)
    expected_keys = list(model.state_dict().keys()) if expected_keys is None else expected_keys

    if logger.level >= logging.WARNING:
        verify_tp_plan(expected_keys, getattr(model, "_tp_plan", None))

    # This offload index if for params explicitly on the "disk" in the device_map
    disk_offload_index = None
    # Prepare parameters offloading if needed
    if load_config.device_map is not None and "disk" in load_config.device_map.values():
        disk_offload_index = accelerate_disk_offload(
            model,
            load_config.disk_offload_folder,
            checkpoint_files,
            load_config.device_map,
            load_config.sharded_metadata,
            load_config.weight_mapping,
        )

    # Warmup cuda to load the weights much faster on devices
    if load_config.device_map is not None and not is_hqq_or_quark:
        expanded_device_map = expand_device_map(load_config.device_map, expected_keys)
        caching_allocator_warmup(model, expanded_device_map, load_config.hf_quantizer)

    error_msgs = []

    if is_deepspeed_zero3_enabled() and not is_quantized:
        if state_dict is None:
            merged_state_dict = {}
            for ckpt_file in checkpoint_files:
                merged_state_dict.update(
                    load_state_dict(
                        ckpt_file,
                        map_location="cpu",
                        weights_only=load_config.weights_only,
                        disable_mmap=load_config.disable_mmap,
                    )
                )
            state_dict = merged_state_dict
        error_msgs, missing_keys = _load_state_dict_into_zero3_model(model, state_dict, load_config)
        # This is not true but for now we assume only best-case scenario with deepspeed, i.e. perfectly matching checkpoints
        loading_info = LoadStateDictInfo(
            missing_keys=missing_keys,
            error_msgs=error_msgs,
            unexpected_keys=set(),
            mismatched_keys=set(),
            conversion_errors={},
        )
    else:
        all_pointer = set()
        if state_dict is not None:
            merged_state_dict = state_dict
        elif checkpoint_files is not None and checkpoint_files[0].endswith(".safetensors") and state_dict is None:
            merged_state_dict = {}

            raise ValueError(
                f"Calling {cls.__name__}.from_pretrained() with the path to a single file or url is not "
                "supported for this tokenizer. Use a model identifier or the path to a directory instead."
            )
        file_id = "vocab_file"
        if pretrained_model_name_or_path.endswith("tokenizer.json"):
            file_id = "tokenizer_file"
        vocab_files[file_id] = pretrained_model_name_or_path
        single_file_id = file_id
    else:
        if gguf_file:
            vocab_files["vocab_file"] = gguf_file
        else:
            # At this point pretrained_model_name_or_path is either a directory or a model identifier name
            additional_files_names = {
                "added_tokens_file": ADDED_TOKENS_FILE,  # kept only for legacy
                "special_tokens_map_file": SPECIAL_TOKENS_MAP_FILE,  # kept only for legacy
                "tokenizer_config_file": TOKENIZER_CONFIG_FILE,
                # tokenizer_file used to initialize a slow from a fast. Properly copy the `addedTokens` instead of adding in random orders
                "tokenizer_file": FULL_TOKENIZER_FILE,
                "chat_template_file": CHAT_TEMPLATE_FILE,
            }

        vocab_files = {**cls.vocab_files_names, **additional_files_names}

        # Check for versioned tokenizer files
        if "tokenizer_file" in vocab_files:
            fast_tokenizer_file = FULL_TOKENIZER_FILE
            resolved_config_file = cached_file(
                pretrained_model_name_or_path,
                TOKENIZER_CONFIG_FILE,
                cache_dir=cache_dir,
                force_download=force_download,
                proxies=proxies,
                token=token,
                revision=revision,
                local_files_only=local_files_only,
                subfolder=subfolder,
                user_agent=user_agent,
                _raise_exceptions_for_missing_entries=False,
                _commit_hash=commit_hash,
            )
            if resolved_config_file is not None:
                with open(resolved_config_file, encoding="utf-8") as reader:
                    tokenizer_config = json.load(reader)
                    if "fast_tokenizer_files" in tokenizer_config:
                        fast_tokenizer_file = get_fast_tokenizer_file(tokenizer_config["fast_tokenizer_files"])
                commit_hash = extract_commit_hash(resolved_config_file, commit_hash)
            vocab_files["tokenizer_file"] = fast_tokenizer_file

        # This block looks for any extra chat template files
        if is_local:
            template_dir = Path(pretrained_model_name_or_path, CHAT_TEMPLATE_DIR)
            if template_dir.is_dir():
                for template_file in template_dir.glob("*.jinja"):
                    template_name = template_file.name.removesuffix(".jinja")
                    vocab_files[f"chat_template_{template_name}"] = f"{CHAT_TEMPLATE_DIR}/{template_file.name}"
        else:
            for template in list_repo_templates(
                pretrained_model_name_or_path,
                local_files_only=local_files_only,
                revision=revision,
                cache_dir=cache_dir,
                token=token,
            ):
                template = template.removesuffix(".jinja")
                vocab_files[f"chat_template_{template}"] = f"{CHAT_TEMPLATE_DIR}/{template}.jinja"

    remote_files = []
    if not is_local and not local_files_only:
        try:
            remote_files = hf_api().list_repo_files(pretrained_model_name_or_path, revision=revision)
        except Exception:
            remote_files = []
    elif pretrained_model_name_or_path and os.path.isdir(pretrained_model_name_or_path):
        remote_files = os.listdir(pretrained_model_name_or_path)

    if "tokenizer_file" in vocab_files and vocab_files["tokenizer_file"] not in "\n".join(remote_files):
        # mistral tokenizer names are different, but we can still convert them if
        # mistral common is not there
        other_pattern = r"tekken\.json|tokenizer\.model\.*|tiktoken\.model" + "|".join(
            getattr(cls, "VOCAB_FILES_NAMES", {}).keys()
        )
        if match := re.search(other_pattern, "\n".join(remote_files)):
            if "spm_file" in vocab_files:
                vocab_files["spm_file"] = match.group()
            else:
                vocab_files["vocab_file"] = match.group()

    resolved_vocab_files = {}
    for file_id, file_path in vocab_files.items():
        if file_path is None:
            resolved_vocab_files[file_id] = None
        elif single_file_id == file_id:
            if os.path.isfile(file_path):
                resolved_vocab_files[file_id] = file_path
        else:
            try:
                resolved_vocab_files[file_id] = cached_file(
                    pretrained_model_name_or_path,
                    file_path,
                    cache_dir=cache_dir,
                    force_download=force_download,
                    proxies=proxies,
                    local_files_only=local_files_only,
                    token=token,
                    user_agent=user_agent,
                    revision=revision,
                    subfolder=subfolder,
                    _raise_exceptions_for_missing_entries=False,
                    _commit_hash=commit_hash,
                )
            except OSError:
                # Re-raise any error raised by cached_file in order to get a helpful error message
                raise
            except Exception:
                # For any other exception, we throw a generic error.
                raise OSError(
                    f"Can't load tokenizer for '{pretrained_model_name_or_path}'. If you were trying to load it from "
                    "'https://huggingface.co/models', make sure you don't have a local directory with the same name. "
                    f"Otherwise, make sure '{pretrained_model_name_or_path}' is the correct path to a directory "
                    f"containing all relevant files for a {cls.__name__} tokenizer."
                )
            commit_hash = extract_commit_hash(resolved_vocab_files[file_id], commit_hash)

    for file_id, file_path in vocab_files.items():
        if file_id not in resolved_vocab_files:
            continue

    return cls._from_pretrained(
        resolved_vocab_files,
        pretrained_model_name_or_path,
        init_configuration,
        *init_inputs,
        token=token,
        cache_dir=cache_dir,
        local_files_only=local_files_only,
        _commit_hash=commit_hash,
        _is_local=is_local,
        trust_remote_code=trust_remote_code,
        **kwargs,
    )

